export const remoteUrlPrefixes = ['https://', 'git@', 'ssh://', 'git://'];
export const isExplicitRemoteUrl = (value) => {
    return remoteUrlPrefixes.some((prefix) => value.startsWith(prefix));
};
const VALID_NAME_PATTERN = '[a-zA-Z0-9](?:[a-zA-Z0-9._-]*[a-zA-Z0-9])?';
const validShorthandRegex = new RegExp(`^${VALID_NAME_PATTERN}/${VALID_NAME_PATTERN}$`);
export const isValidShorthand = (remoteValue) => {
    return validShorthandRegex.test(remoteValue);
};
const EXPLICIT_URL_NAME_PATTERN = '[a-zA-Z0-9._-]+';
const validExplicitUrlOwnerRepoRegex = new RegExp(`^${EXPLICIT_URL_NAME_PATTERN}/${EXPLICIT_URL_NAME_PATTERN}$`);
export const isValidExplicitUrlOwnerRepo = (ownerSlashRepo) => {
    return validExplicitUrlOwnerRepoRegex.test(ownerSlashRepo);
};
